namespace Quantum.Hardware {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Diagnostics;

    // Demonstrate T1 decay by waiting and measuring
    operation T1Decay(waitTime : Double) : Result {
        use q = Qubit();

        // Prepare |1⟩
        X(q);

        // Wait (simulated by idle operations)
        for (i in 0..Int(waitTime)) {
            // Idle - in real hardware, this would be actual wait time
            Identity(q);
        }

        // Measure population of |1⟩
        let result = M(q);
        Reset(q);

        return result;
    }

    // Ramsey experiment for T2 measurement
    operation RamseyExperiment(waitTime : Double, phase : Double) : Result {
        use q = Qubit();

        // Prepare superposition
        H(q);

        // Wait with phase evolution
        Rz(phase, q);

        // Rotate back and measure
        H(q);
        let result = M(q);
        Reset(q);

        return result;
    }

    @EntryPoint()
    operation CharacterizeQubit() : Unit {
        Message("Characterizing qubit coherence...");

        // Run multiple trials to estimate T1
        mutable oneCount = 0;
        for (i in 0..99) {
            let result = T1Decay(0.0);
            if (result == One) {
                set oneCount += 1;
            }
        }
        Message($"Initial |1⟩ population: {IntAsDouble(oneCount) / 100.0}");
    }
}
